package main

import "fmt"

func main() {
	// Declare and initialize arrays
	var a [3]int
	fmt.Println("Zero array:", a)

	b := [3]int{1, 2, 3}
	fmt.Println("Literal array:", b)

	c := [...]string{"Go", "Python", "Rust"}
	fmt.Println("Auto-sized array:", c, "len:", len(c))

	// Array comparison
	x := [3]int{1, 2, 3}
	y := [3]int{1, 2, 3}
	fmt.Println("Arrays equal:", x == y)

	// Multi-dimensional array
	matrix := [3][3]int{
		{1, 2, 3},
		{4, 5, 6},
		{7, 8, 9},
	}
	fmt.Println("Matrix:")
	for _, row := range matrix {
		fmt.Println(row)
	}

	// Array is value type
	original := [3]int{10, 20, 30}
	copy := original
	copy[0] = 99
	fmt.Println("Original:", original)
	fmt.Println("Copy:", copy)
}
